    @Test void postgresRestartAndReplacementGuardPermitOnlyHistoricalInspection()throws Exception {
        handoff();var observed=recoveryService().verify(guard,bootstrap,review);var before=nativeSnapshot();var started=jdbc.queryForObject("SELECT pg_postmaster_start_time()",OffsetDateTime.class);String signal=System.getProperty("ddip.test.verification-restart-signal");if(signal!=null){Files.writeString(Path.of(signal),"READY");long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(45);while(!Files.exists(Path.of(signal+".done")) && System.nanoTime()<end)java.util.concurrent.locks.LockSupport.parkNanos(10000000);assertThat(Files.exists(Path.of(signal+".done"))).isTrue();assertThat(jdbc.queryForObject("SELECT pg_postmaster_start_time()",OffsetDateTime.class)).isAfter(started);}
        guard.close();guard=InstallationHostGuard.acquire(binding);assertThat(recoveryService().inspect(guard,control).classification()).isEqualTo("VERIFIED_PUBLICATION");assertThatThrownBy(()->recoveryService().verify(guard,bootstrap,review)).hasMessage("OWNERSHIP_LOST");assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }

    @ParameterizedTest @ValueSource(strings={"heartbeat","outage"}) void liveHeartbeatAndDatabaseLossFenceTheActiveChild(String mode)throws Exception {
        handoff();var before=nativeSnapshot();var beats=new AtomicInteger();var process=new ReadOnlyVerifierProcess(){@Override Result run(List<String> c,Map<String,String> env,Path dir,Duration timeout,Observer o){var command=new ArrayList<>(c);command.set(6,"import time;time.sleep(6)\n"+command.get(6));return super.run(command,env,dir,timeout,new Observer(){public void beforeStart(){o.beforeStart();}public void started(InstallationHostGuard.ProcessIdentity child){o.started(child);}public void heartbeat(){beats.incrementAndGet();if(mode.equals("outage"))outage(true);o.heartbeat();}});}};
        try{if(mode.equals("outage"))assertThatThrownBy(()->recoveryService(process).verify(guard,bootstrap,review)).hasMessage("MANAGEMENT_UNAVAILABLE");else{var observed=recoveryService(process).verify(guard,bootstrap,review);assertThat(observed.classification()).isEqualTo("VERIFIED_PUBLICATION");assertThat(observed.stage().owner().worker().coordinatorVersion()).isGreaterThan(recoveryOwner.worker().coordinatorVersion());}}finally{if(mode.equals("outage"))outage(false);}
        assertThat(beats.get()).isPositive();assertThat(recoveryService().inspect(guard,control).classification()).isEqualTo(mode.equals("outage")?"INCONCLUSIVE":"VERIFIED_PUBLICATION");assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }
    @Test void competingInvocationsCannotLaunchSecondChild()throws Exception {
        handoff();var before=nativeSnapshot();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();var process=new ReadOnlyVerifierProcess(){@Override Result run(List<String> c,Map<String,String> e,Path d,Duration t,Observer o){calls.incrementAndGet();entered.countDown();try{assertThat(release.await(10,TimeUnit.SECONDS)).isTrue();}catch(InterruptedException ex){throw new AssertionError(ex);}return super.run(c,e,d,t,o);}};
        try(var pool=Executors.newSingleThreadExecutor()){var first=pool.submit(()->recoveryService(process).verify(guard,bootstrap,review));try{assertThat(entered.await(10,TimeUnit.SECONDS)).isTrue();assertThatThrownBy(()->recoveryService(process).verify(guard,bootstrap,review)).hasMessage("HANDOFF_UNRESOLVED");assertThat(calls.get()).isEqualTo(1);}finally{release.countDown();}assertThat(first.get(30,TimeUnit.SECONDS).classification()).isEqualTo("VERIFIED_PUBLICATION");}finally{release.countDown();}assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }
    @Test void validOutputChangedSinceOriginalVerificationIsNotRecoveredSuccess()throws Exception {
        UUID cp=UUID.randomUUID();var f=new PreflightFiles(guard,run,owner.attemptId(),cp,"VERIFY_RESULT");var c=SourceJson.object();for(String key:List.of("protocolVersion","runId","attemptId","ownerEpoch","itemOrdinal","capturedConfigSha256","runtime"))c.set(key,originalPack.get("command").get(key));c.put("stage","VERIFY_RESULT").put("checkpointId",cp.toString()).put("retainedSha256",SourceJson.sha(SourceJson.canonical(originalPack))).put("nativeFingerprint",fingerprint());byte[] raw=SourceJson.canonical(c);f.write("command.json",raw,PreflightFiles.SMALL);f.write("retained.json",SourceJson.canonical(originalPack),PreflightFiles.LARGE);
        var frozen=originalPack.get("bundle").get("capturedSelection");var runtime=ReliabilityRuntime.load(jdbc,tx,guard,owner,RUNTIME,frozen);var child=new ReadOnlyVerifierProcess().run(runtime.command(f.directory.resolve("command.json"),true),runtime.environment(),runtime.scratch(),Duration.ofSeconds(30),new ReadOnlyVerifierProcess.Observer(){public void beforeStart(){}public void started(InstallationHostGuard.ProcessIdentity c){}public void heartbeat(){}});assertThat(child.exitCode()).isZero();byte[] e=f.read("evidence.json",PreflightFiles.LARGE);var anchor=SourceJson.object().put("evidenceSha256",SourceJson.sha(e)).put("commandSha256",SourceJson.sha(raw)).put("resultSha256",SourceJson.sha(f.read("result.json",PreflightFiles.SMALL))).put("cleanup","OBSERVED_CLEAN_EXIT");byte[] validated=SourceJson.canonical(anchor);f.write("verified.json",validated,PreflightFiles.SMALL);
        jdbc.update("INSERT INTO ddip_management.stage_invocations(attempt_id,stage,item_ordinal,checkpoint_id,state,input_evidence_sha256,intended_identity,command_address,command_sha256,result_address,result_sha256,finished_at) VALUES (?,'VERIFY_RESULT',0,?,'VERIFIED',?,?,?,?,?,?,now())",owner.attemptId(),cp,SourceJson.sha(raw),fingerprint(),f.address+"/command.json",SourceJson.sha(raw),f.address+"/verified.json",SourceJson.sha(validated));
        Path marker=publication().resolve("complete.json");var complete=(ObjectNode)SourceJson.parse(Files.readAllBytes(marker));complete.put("completed_at","2026-10-25T00:00:00.000000Z");Files.write(marker,SourceJson.canonical(complete));handoff();var before=nativeSnapshot();var observed=recoveryService().verify(guard,bootstrap,review);assertThat(observed.classification()).isEqualTo("OUTPUT_CHANGED");assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }

    @ParameterizedTest @ValueSource(strings={"dependency","output"}) void deniedIoIsUnavailableEvidenceNotKnownCorruption(String kind)throws Exception {
        handoff();var before=nativeSnapshot();Path blocked=kind.equals("output")?publication():Path.of(fixture.get("bundle").get("bindings").get("batch").get("root").stringValue());var permissions=Files.getPosixFilePermissions(blocked);RecoveryVerification.Observation observed;
        var process=new ReadOnlyVerifierProcess(){@Override Result run(List<String> c,Map<String,String> env,Path dir,Duration timeout,Observer o){try{return super.run(c,env,dir,timeout,new Observer(){public void beforeStart(){o.beforeStart();try{Files.setPosixFilePermissions(blocked,Set.of());}catch(Exception ex){throw new AssertionError(ex);}}public void started(InstallationHostGuard.ProcessIdentity child){o.started(child);}public void heartbeat(){o.heartbeat();}});}finally{try{Files.setPosixFilePermissions(blocked,permissions);}catch(Exception ex){throw new AssertionError(ex);}}}};
        observed=recoveryService(process).verify(guard,bootstrap,review);
        assertThat(observed.classification()).isEqualTo(kind.equals("output")?"OUTPUT_UNAVAILABLE":"DEPENDENCY_UNAVAILABLE");assertThat(recoveryService().inspect(guard,control).classification()).isEqualTo(observed.classification());assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }

    @ParameterizedTest @ValueSource(strings={"INTENT","AUTHORIZED","CHILD","RESULT"}) void injectedTransactionFailuresNeverCommitPartialStageEffects(String point)throws Exception {
        handoff();var before=nativeSnapshot();var svc=new RecoveryVerification(jdbc,tx,handoffs,new ReadOnlyVerifierProcess(),step->{if(step.name().equals(point))throw new RecoveryFailure(RecoveryFailure.Code.INVALID_REQUEST);});
        assertThatThrownBy(()->svc.verify(guard,bootstrap,review)).hasMessage("INVALID_REQUEST");assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE attempt_id=? AND state IN ('VERIFIED','FAILED','UNKNOWN')",Long.class,control)).isZero();
        if(point.equals("INTENT")){assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE attempt_id=?",Long.class,control)).isZero();assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.attempts WHERE attempt_id=?",String.class,control)).isEqualTo("CLAIMED");}else assertThat(recoveryService().inspect(guard,control).classification()).isEqualTo("INCONCLUSIVE");assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }

    @Test void contradictoryOriginalPublicationCommandCannotBeRetargeted()throws Exception {
        guard.close();guard=null;contradictoryPublish=true;jdbc.execute("DROP SCHEMA ddip_management CASCADE");new SchemaLifecycle(org.flywaydb.core.Flyway.configure().dataSource(jdbc.getDataSource()).defaultSchema("ddip_management").schemas("ddip_management").load(),jdbc,new JdbcCoordinatorRepository(jdbc,tx,INSTALL)).verify(true);provision("JSONL");handoff();var before=nativeSnapshot();assertThatThrownBy(()->recoveryService().verify(guard,bootstrap,review)).hasMessage("EVIDENCE_CHANGED");assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE attempt_id=?",Long.class,control)).isZero();assertThat(nativeSnapshot()).isEqualTo(before);occupied();
    }

